# %% Contacts_v2.ipynb 4
@patch
def validate(self: Contact):
    "Validates contact data and returns a dictionary of errors"
    print(self)
    errors = {}
    if not self.first: errors["first"] = "First name is required"
    if not self.email: errors["email"] = "Email is required"
    elif any(c.email == self.email and (c.id != self.id) for c in contacts()):
        errors["email"] = "Email already exists"
   
    return errors

